    public Figures previewed(Sheet sheet, RateChain sheetRates, List<Person> sheetPeople, List<Claim> sheetClaims,
            LocalDate preview) {
        if (sheet == null || preview == null) {
            return of(sheet, sheetRates, sheetPeople, sheetClaims);
        }
