     * proofReceipts and proofPhotos are how many of its proofs are of each kind; held is whether it is held;
     * shares are the other people holding a part of its due, in the order given; reviewAssigned is the user a steward
     * assigned it to review (null when never assigned).
     */
    public record ClaimView(long id, long personId, String amount, LocalDate date, String note, ClaimStatus status,
            String number, String settledDue, String openedBy, boolean stated, String statedDue, String corrects,
            LocalDate dueBy, LocalDate deferredUntil, List<LogLine> log, int proofs, String splitFrom,
            String lockedBy, boolean lateEntry, LocalDate remindedOn, String ref, List<String> tags,
            String voidReason, List<CommentLine> comments, String editedBy, Integer batch, List<LineView> lines,
            boolean waived, String statedLate, int proofReceipts, int proofPhotos, boolean held,
            List<ShareView> shares, String reviewAssigned) {

        public static ClaimView of(Claim claim) {
            return new ClaimView(claim.getId(), claim.getPersonId(), claim.getAmount().toPlainString(),
                    claim.getDate(), claim.getNote(), claim.getStatus(), claim.getNumber(),
                    claim.getSettledDue() == null ? null : claim.getSettledDue().toPlainString(),
                    claim.getOpenedBy(), claim.isStated(),
                    claim.getBoundDue() == null ? null : claim.getBoundDue().toPlainString(), claim.getCorrects(),
                    claim.getDueBy(), claim.getDeferredUntil(), claim.getLog().stream().map(LogLine::of).toList(),
                    claim.getProofs(), claim.getSplitFrom(), claim.getLockedBy(), claim.isLateEntry(),
                    claim.getRemindedOn(), claim.getRef(), claim.tagList(), claim.getVoidReason(),
                    claim.getComments().stream().map(CommentLine::of).toList(), claim.getEditedBy(),
                    claim.getSettleBatch(), claim.getLines().stream().map(LineView::of).toList(),
                    claim.isWaived(),
                    claim.getBoundLate() == null ? null : claim.getBoundLate().toPlainString(),
                    claim.getProofReceipts(), claim.getProofPhotos(), claim.isHeld(),
                    claim.getShares().stream().map(ShareView::of).toList(), claim.getReviewAssigned());
        }
    }

    /** A line of a claim's status log: the status it took, by whom, on the sheet's today then, at the due it had
     *  then with exactly two decimals (null when it had none). */
    public record LogLine(ClaimStatus status, String by, LocalDate on, String due) {

        public static LogLine of(ClaimLogEntry entry) {
            return new LogLine(entry.getStatus(), entry.getBy(), entry.getOn(),
                    entry.getDue() == null ? null : entry.getDue().toPlainString());
        }
    }

    /** A comment on a claim: who wrote it, on the sheet's today then, and its text. */
    public record CommentLine(String by, LocalDate on, String text) {

        public static CommentLine of(ClaimComment comment) {
            return new CommentLine(comment.getBy(), comment.getOn(), comment.getText());
        }
    }

    /** A share of a claim: the person holding it and their share percent with exactly two decimals. */
    public record ShareView(long personId, String share) {

        public static ShareView of(ClaimShare share) {
            return new ShareView(share.getPersonId(), share.getShare().toPlainString());
        }
    }

    /** A share to give a claim: the person to share it with and their share percent; the service refuses what is
     *  out of range. */
    public record ShareForm(@NotNull Long personId, @NotNull @Digits(integer = 3, fraction = 2) BigDecimal share) {
    }

    /** A line of a claim: its label, its quantity and its unit amount with exactly two decimals. */
    public record LineView(String label, int qty, String unit) {

        public static LineView of(ClaimLine line) {
            return new LineView(line.getLabel(), line.getQty(), line.getUnit().toPlainString());
        }
    }

    /** A line to add to a claim: a label, a quantity and a unit amount; the service refuses what is out of range. */
    public record LineForm(@Size(max = 200) String label, @NotNull Integer qty,
            @NotNull @Digits(integer = 12, fraction = 2) BigDecimal unit) {
    }

    /** The user to assign a REVIEW claim to review; a blank one is refused. */
    public record ReviewAssignForm(@Size(max = 100) String user) {
    }

    /** A comment to add to a claim; an empty one is refused. */
    public record CommentForm(@Size(max = 1000) String text) {
    }

    /** A claim's values as the form submits them; a missing date takes the sheet's today. A negative amount is a
     *  correction, which names in corrects the number of the claim it corrects. */
    public record ClaimForm(
            @NotNull @Digits(integer = 12, fraction = 2) BigDecimal amount,
            LocalDate date,
            @Size(max = 1000) String note,
            @Size(max = 120) String corrects,
            @Size(max = 120) String ref,
            @Size(max = 1000) String tags) {
     *  pendingSla is the pending SLA in days, null when there is none;
     *  maxOpen is the maximum of open claims per person, null when there is none;
     *  scoreMid and scoreHigh are the score thresholds, each null when there is none;
     *  scoreLog is "on" while the score log switch is on, else null;
     *  proofKinds is the sheet's proof kinds, comma separated, null when there are none;
     *  defaultGrade is the sheet's default grade, null when it sets none (then A);
     *  retiredGrades is the grades retired on the sheet, in order;
     *  grades is the sheet's grades: A, B and C, then those added, in order;
     *  asOf is the date the sheet is shown as of, when it is (then the sheet is as it stood at the end of it, and today is that date), else null. */
    public record SheetView(String id, LocalDate today, String clerkLimit, String floor, int terms, String latePct,
            LocalDate policyDate, LocalDate periodNumberingFrom, Map<String, Integer> gradeTerms, String cap,
            List<DatedSettingView> settings, String proofThreshold, Map<String, String> permissions, Integer graceDays, boolean archived,
            LocalDate asOf, String noteThreshold, LocalDate entryDate, Map<String, Integer> gradeGrace,
            Map<String, String> gradeProofThreshold, Integer settleBatch, String pot, String parent, int fiscalStartMonth,
            String alertThreshold, String rounding, String reviewThreshold, Integer escalateAfter, Integer reviewSla,
            String proofKinds, String defaultGrade, Map<String, String> gradeClerkLimit, Integer scoreMid, Integer scoreHigh,
            String scoreLog, Integer maxOpen, List<String> retiredGrades,
            List<String> grades, Integer pendingSla) {

        static SheetView of(Sheet sheet) {
            return of(sheet, null);
        }

        static SheetView of(Sheet sheet, LocalDate asOf) {
            return new SheetView(sheet.getId(), sheet.getToday(),
                    sheet.getClerkLimit() == null ? null : sheet.getClerkLimit().toPlainString(),
                    sheet.getFloor().toPlainString(), sheet.getTerms(), sheet.getLatePct().toPlainString(), sheet.getPolicyDate(),
                    sheet.getPeriodNumberingFrom(), sheet.getGradeTerms(),
                    sheet.getCap() == null ? null : sheet.getCap().toPlainString(),
                    sheet.getSettings().stream().map(s -> new DatedSettingView(s.getKey(), s.getFrom(), s.getValue())).toList(),
                    sheet.getProofThreshold() == null ? null : sheet.getProofThreshold().toPlainString(),
                    sheet.getPermissions(), sheet.getGraceDays(), sheet.isArchived(), asOf,
                    sheet.getNoteThreshold() == null ? null : sheet.getNoteThreshold().toPlainString(),
                    sheet.getEntryDate(), sheet.getGradeGrace(), sheet.getGradeProofThresholds(),
                    sheet.getLastSettleBatch() == 0 ? null : sheet.getLastSettleBatch(),
                    sheet.getPot() == null ? null : sheet.getPot().toPlainString(), sheet.getParentId(),
                    sheet.getFiscalStartMonth(),
                    sheet.getAlertThreshold() == null ? null : sheet.getAlertThreshold().toPlainString(),
                    sheet.getRounding(),
                    sheet.getReviewThreshold() == null ? null : sheet.getReviewThreshold().toPlainString(),
                    sheet.getEscalateAfter(), sheet.getReviewSla(), sheet.getProofKinds(),
                    sheet.getDefaultGrade(), sheet.getGradeClerkLimits(), sheet.getScoreMid(), sheet.getScoreHigh(),
                    sheet.isScoreLog() ? "on" : null, sheet.getMaxOpen(), sheet.getRetiredGrades(),
                    sheet.getGrades(), sheet.getPendingSla());
        }
    }

    /** A dated setting's value from a from-date (null: from the beginning of time); a null value means none. */
    public record DatedSettingView(String key, LocalDate from, String value) {
    }

    public record TodayChange(@NotNull LocalDate today) {
    }

    /** The sheet's settings as the form submits them; a missing clerk limit means no limit, a missing from-date the sheet's today. */
    public record SettingsChange(@DecimalMin("0.00") @Digits(integer = 12, fraction = 2) BigDecimal clerkLimit, LocalDate from) {
    }

    /** The sheet's floor as the form submits it. */
    public record FloorChange(@NotNull @DecimalMin("0.00") @Digits(integer = 12, fraction = 2) BigDecimal floor, LocalDate from) {
    }

    /** The sheet's terms, in days, as the form submits them. */
    public record TermsChange(@NotNull @Min(0) @Max(36500) Integer terms, LocalDate from) {
    }

    /** A grade's own terms, in days, as the form submits them; missing ones leave the grade on the sheet's terms. */
    public record GradeTermsChange(@Min(0) @Max(36500) Integer terms, LocalDate from) {
    }

    /** The sheet's late percent as the form submits it. */
    public record LatePctChange(@NotNull @DecimalMin("0.00") @Digits(integer = 3, fraction = 2) BigDecimal latePct, LocalDate from) {
    }

    /** The sheet's policy date as the form submits it; a missing one means the sheet's today. */
    public record PolicyDateChange(LocalDate policyDate) {
    }

    /** The sheet's entry date as the form submits it; a missing one means off. */
    public record EntryDateChange(LocalDate entryDate) {
    }

    /** The sheet's period numbering from as the form submits it; a missing one means off. */
