/** The sheet's today ('' before a sheet is loaded). */
private readonly todayNow = computed(() => this.sheets.current()?.today ?? '');
/** Whether each claim counts in the live totals: a deferred claim does not, nor do a person's open claims
 *  dated within one of their holds, or all of them once their retirement date is reached, when not bound by a
 *  statement. */
private readonly countsNow = computed(() => {
  const today = this.todayNow();
  const byPerson = new Map(this.people().map((p) => [p.id, countsWithHolds(p.holds, today, p.retiredFrom)]));
  return (c: ClaimView) => (byPerson.get(c.personId) ?? countsWithHolds([], today))(c);
});
/** Whether each claim counts in what is claimed: as in the live totals, except that a hold does not take it out. */
private readonly countsClaimedNow = computed(() => {
  const today = this.todayNow();
  const byPerson = new Map(this.people().map((p) => [p.id, countsClaimed(today, p.retiredFrom)]));
  return (c: ClaimView) => (byPerson.get(c.personId) ?? countsClaimed(today))(c);
});
protected readonly claimedTotal = computed(() =>
  money(this.claims().filter(this.countsClaimedNow()).filter((c) => c.corrects === null).reduce((sum, c) => sum + cents(c.amount), 0)),
);
/** Each person's due-total in whole cents: the sum of the dues of their claims that count (0 with none),
 *  at most the sheet's cap less their cut total (not below 0); null when neither their grade in force today nor the grade any of those claims is at has a rate in
 *  force today, and none of those claims has a due. */
protected readonly dueByPerson = computed(() => {
  const cap = this.capCents();
  return new Map([...this.uncappedDueByPerson()].map(([id, due]) =>
    [id, due === null || cap === null ? due : Math.min(due, Math.max(0, cap - this.cutOf(id)))]));
});
/** The sheet's cap in whole cents; null with none. */
private readonly capCents = computed(() => {
  const cap = this.sheets.current()?.cap;
  return cap === null || cap === undefined ? null : cents(cap);
});
/** Each person's due-total before the cap, in whole cents; null as for the due-total. */
private readonly uncappedDueByPerson = computed(() => {
  const today = this.rates.byGrade();
  const dueTerms = this.sheets.current() ?? DEFAULT_DUE_TERMS;
  const byPerson = new Map<number, number | null>();
  for (const p of this.people()) {
    const counting = this.claimsOf(p.id).filter(countsWithHolds(p.holds, this.todayNow(), p.retiredFrom));
    const grades = [this.gradeToday(p), ...counting.map((c) => gradeOn(p, c.date))];
    const dues = [
      ...counting.map((c) => this.claimDue(p, c, dueTerms)).map((due, i) => due === null ? null : this.ownPart(counting[i], due, dueTerms)),
      ...(this.heldParts().get(p.id) ?? []).map((h) => h.part),
    ].filter((due) => due !== null);
    if (!grades.some((g) => today.has(g)) && dues.length === 0) {
      byPerson.set(p.id, null);
      continue;
    }
    byPerson.set(p.id, dues.reduce((sum, due) => sum + due, 0));
  }
  return byPerson;
});
/** The parts each person holds of other people's claims that count (as for their own person), by holder id: each
 *  as `holderPart`, in whole cents; a claim with no due gives none, nor does one whose holder's grade has no rate. */
private readonly heldParts = computed(() => {
  const dueTerms = this.sheets.current() ?? DEFAULT_DUE_TERMS;
  const byPerson = new Map<number, { claim: ClaimView; part: number }[]>();
  for (const p of this.people()) {
    for (const c of this.claimsOf(p.id).filter(countsWithHolds(p.holds, this.todayNow(), p.retiredFrom))) {
      if (!c.shares?.length) continue;
      const due = this.claimDue(p, c, dueTerms);
      if (due === null) continue;
      for (const sh of c.shares) {
        const part = this.holderPart(c, sh, due, dueTerms);
        if (part === null) continue;
        byPerson.set(sh.personId, [...(byPerson.get(sh.personId) ?? []), { claim: c, part }]);
      }
    }
  }
  return byPerson;
});
/** Each person's due-total before the cap split by status, in whole cents: the dues of their SETTLED claims that
 *  count (at their frozen figures, corrections included) and of their OPEN and PENDING claims that count. */
private readonly splitByPerson = computed(() => {
  const dueTerms = this.sheets.current() ?? DEFAULT_DUE_TERMS;
  const byPerson = new Map<number, Split>();
  for (const p of this.people()) {
    const split = { ...NO_SPLIT };
    for (const c of this.claimsOf(p.id).filter(countsWithHolds(p.holds, this.todayNow(), p.retiredFrom))) {
      const due = this.claimDue(p, c, dueTerms) ?? 0;
      if (c.status === 'SETTLED') {
        split.settled += this.ownPart(c, due, dueTerms);
        if (c.corrects == null) split.scored += due;
      }
      else if (c.status === 'OPEN' || c.status === 'PENDING') split.open += this.ownPart(c, due, dueTerms);
    }
    for (const h of this.heldParts().get(p.id) ?? []) {
      if (h.claim.status === 'SETTLED') split.settled += h.part;
      else if (h.claim.status === 'OPEN' || h.claim.status === 'PENDING') split.open += h.part;
    }
    byPerson.set(p.id, split);
  }
  return byPerson;
});
/** Each person's cut total in whole cents: their cuts across every pool they are a member of, added up; a pool
 *  that shows no cuts adds nothing. */
private readonly cutByPerson = computed(() => {
  const byPerson = new Map<number, number>();
  for (const pool of this.pools.all()) {
    for (const m of pool.members) {
      if (m.personId !== null && m.cut !== null) {
        byPerson.set(m.personId, (byPerson.get(m.personId) ?? 0) + cents(m.cut));
      }
    }
  }
  return byPerson;
});
protected cutOf(personId: number): number {
  return this.cutByPerson().get(personId) ?? 0;
}
/** The sheet's cut total in whole cents: everyone's cut total added up, trimmed of the highest and lowest. */
protected readonly cutTotal = computed(() =>
  trimmedSum(this.people().map((p) => this.cutOf(p.id))));
/** Everyone's settled-total and open-total, each added up and trimmed of the highest and lowest. */
protected readonly splitTotals = computed(() => {
  const splits = [...this.splitByPerson().values()];
  return {
    settled: trimmedSum(splits.map((split) => split.settled)),
    open: trimmedSum(splits.map((split) => split.open)),
  };
});
/** For every tag used on the sheet's claims or people, in tag order, the dues in whole cents of the claims that
 *  count which carry it, or whose person does, once (none counting as 0); a claim with two tags counts in both. */
protected readonly tagTotals = computed(() => {
  const dueTerms = this.sheets.current() ?? DEFAULT_DUE_TERMS;
  const totals = new Map<string, number>();
  for (const c of this.claims()) for (const tag of c.tags) totals.set(tag, 0);
  for (const p of this.people()) for (const tag of p.tags) totals.set(tag, 0);
  for (const p of this.people()) {
    for (const c of this.claimsOf(p.id).filter(countsWithHolds(p.holds, this.todayNow(), p.retiredFrom))) {
      const tags = new Set([...c.tags, ...p.tags]);
      if (tags.size === 0) continue;
      const due = this.claimDue(p, c, dueTerms) ?? 0;
      for (const tag of tags) totals.set(tag, (totals.get(tag) ?? 0) + due);
    }
  }
  return [...totals].sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0)).map(([tag, cents]) => ({ tag, cents }));
});
/** For every calendar month (yyyy-mm) any of the sheet's claims is dated in, in month order, the dues in whole
 *  cents of the claims dated in it that count (none counting as 0). */
protected readonly monthTotals = computed(() => {
  const dueTerms = this.sheets.current() ?? DEFAULT_DUE_TERMS;
  const totals = new Map<string, number>();
  for (const c of this.claims()) totals.set(c.date.slice(0, 7), 0);
  for (const p of this.people()) {
    for (const c of this.claimsOf(p.id).filter(countsWithHolds(p.holds, this.todayNow(), p.retiredFrom))) {
      const month = c.date.slice(0, 7);
      totals.set(month, (totals.get(month) ?? 0) + (this.claimDue(p, c, dueTerms) ?? 0));
    }
  }
  return [...totals].sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0)).map(([month, cents]) => ({ month, cents }));
});
/** Everyone's due-total added up, skipping those with none, trimmed of the highest and lowest. */
protected readonly dueTotal = computed(() =>
  money(trimmedSum([...this.dueByPerson().values()].filter((due) => due !== null))),
);
/** Over the sheet's own people as shown here and its descendants': how many distinct people (those whose names or
 *  aliases match as names are compared being one), and everyone's due-total, overdue-total, settled-total,
 *  open-total and cut total trimmed once of the
 *  highest and lowest; the sheet's own per-grade due-totals and per-status claim counts added to its descendants';
 *  while the sheet is shown as of a date, its descendants' are as they stood then too. */
protected readonly consolidated = computed(() => {
  const d = this.descendants();
  const dueByPerson = this.dueByPerson();
  const overdueByPerson = this.overdueByPerson();
  const splitByPerson = this.splitByPerson();
  const tree = [
    ...this.people().map((p) => ({
      names: [p.name, ...(p.aliases ?? [])],
      due: dueByPerson.get(p.id) ?? null,
      overdue: overdueByPerson.get(p.id)?.cents ?? 0,
      settled: splitByPerson.get(p.id)?.settled ?? 0,
      open: splitByPerson.get(p.id)?.open ?? 0,
      cut: this.cutOf(p.id),
    })),
    ...d.people.map((p) => ({
      names: p.names,
      due: p.dueTotal === null ? null : cents(p.dueTotal),
      overdue: cents(p.overdueTotal),
      settled: cents(p.settledTotal),
      open: cents(p.openTotal),
  // A claim whose editor this user has open (it holds their lock) shows its editor again when the sheet is
  // re-loaded.
  effect(() => {
    const user = this.session.user();
    const mine = this.claims().find((c) => c.status === 'DRAFT' && c.lockedBy !== null && c.lockedBy === user);
    untracked(() => {
      if (mine && this.editingId() === null) this.open(mine);
    });
  });
}

protected dueOf(c: ClaimView): string {
  const grade = gradeOn(this.grades(), c.date);
  const rates = this.ratesByGrade().get(grade) ?? NO_RATES;
  const due = claimDueCents(c, rates, this.sheets.current() ?? DEFAULT_DUE_TERMS, roundingDate(c, this.claims()), grade);
  return due === null ? NOT_AVAILABLE : money(due);
}

protected dueByOf(c: ClaimView): string {
  return c.dueBy;
}

protected overdueOf(c: ClaimView): boolean {
  const sheet = this.sheets.current();
  return sheet !== null && isOverdue(c, sheet.today, graceOn(sheet.settings, gradeOn(this.grades(), c.date), c.date));
}

