protected nameShown(p: PersonView): string {
  return nameWithGrade(p, this.todayNow());
}

/** The person's grade in force on the sheet's today. */
protected gradeToday(p: PersonView): Grade {
  return gradeOn(p, this.sheets.current()?.today ?? '');
}

/** What a claim's own person counts of its due, in whole cents: the due less its holders' parts (one with no rate
 *  taking 0.00). */
private ownPart(c: ClaimView, due: number, dueTerms: DueTerms): number {
  return (c.shares ?? []).reduce((rest, sh) => rest - (this.holderPart(c, sh, due, dueTerms) ?? 0), due);
}

/** A holder's part of a claim with this due, in whole cents: a settled claim keeps its parts frozen, its settled
 *  due times the holder's share divided by 100, rounded half to even; any other claim's is its amount times the
 *  share divided by 100, times the rate of the holder's own grade in force on the claim's date divided by 100,
 *  rounded as the claim rounds; null when their grade has no rate then. */
private holderPart(c: ClaimView, sh: { personId: number; share: string }, due: number, dueTerms: DueTerms): number | null {
  if (c.settledDue !== null) return sharePartCents(due, sh.share);
  const holder = this.people().find((p) => p.id === sh.personId);
  if (!holder) return null;
  const rate = rateOnLine(this.rates.lineByGrade().get(gradeOn(holder, c.date)) ?? NO_RATES, c.date, c.id);
  if (rate === undefined) return null;
  return holderPartCents(cents(c.amount), sh.share, rate, roundsHalfUp(roundingDate(c, this.claimsOf(c.personId)), dueTerms));
}

/** A claim's due in whole cents, at the rates of its person's grade in force on its date; null with none. */
private claimDue(p: PersonView, c: ClaimView, dueTerms: DueTerms): number | null {
  const grade = gradeOn(p, c.date);
  return claimDueCents(c, this.rates.lineByGrade().get(grade) ?? NO_RATES, dueTerms,
    roundingDate(c, this.claimsOf(p.id)), grade);
}

protected sortBy(key: string): void {
  if (!(SORT_KEYS as readonly string[]).includes(key)) return;
  const user = this.session.user()?.trim().toLowerCase() ?? '';
  this.sortByUser.update((m) => new Map(m).set(user, key as SortKey));
}

protected dueOf(p: PersonView): string {
  const due = this.dueByPerson().get(p.id);
  return due === null || due === undefined ? NOT_AVAILABLE : money(due);
}

protected splitOf(personId: number): Split {
  return this.splitByPerson().get(personId) ?? NO_SPLIT;
}

/** How far the person's figures (their due-total before the cap plus their cut total) add up above the cap, in
 *  whole cents; 0 when they do not, there is no cap, or they have no due-total (none, or nothing due). */
protected excessOf(personId: number): number {
  const sum = this.uncappedDueByPerson().get(personId) ?? null;
  const cap = this.capCents();
  return sum === null || sum === 0 || cap === null ? 0 : Math.max(0, sum + this.cutOf(personId) - cap);
}

/** Download the people as CSV, in list order, retired people included. */
protected exportCsv(): void {
  const lines = [
    ['name', 'grade', 'retired-from', 'due-total'],
    ...this.people().map((p) => [p.name, this.gradeToday(p), p.retiredFrom ?? '', this.dueOf(p)]),
  ].map((fields) => fields.map(csvField).join(',') + '\n');
  this.download(lines, 'people');
}

/** Download the claims as CSV: people in list order, retired people included, each person's claims oldest
 *  first, with the figures as the claims list shows them. */
protected exportClaims(): void {
  const dueTerms = this.sheets.current() ?? DEFAULT_DUE_TERMS;
  const lines = [
    ['person', 'number', 'date', 'amount', 'due', 'status', 'period'],
    ...this.people().flatMap((p) => [...this.claimsOf(p.id)].reverse().map((c) => {
      const due = this.claimDue(p, c, dueTerms);
      return [p.name, c.number ?? '', c.date, c.amount,
        due === null ? NOT_AVAILABLE : money(due), c.status, periodOn(this.periods.list(), c.dueBy)?.name ?? ''];
    })),
  ].map((fields) => fields.map(csvField).join(',') + '\n');
  this.download(lines, 'claims');
}

